// Flatten each matched email into a compact record the model can read.
const strip = (h) => String(h || '').replace(/<[^>]+>/g, ' ').replace(/&[a-z#0-9]+;/g, ' ').replace(/\s+/g, ' ').trim();
const out = [];
let i = 0;
for (const it of $input.all()) {
  const j = it.json;
  const from = j.from?.value?.[0]?.address || j.From || j.from || '';
  const subject = j.subject || j.Subject || '';
  const date = j.date || j.internalDate || j.Date || '';
  const body = strip(j.text || j.textPlain || j.snippet || j.textAsHtml || '');
  out.push({ json: { i: i++, id: j.id || '', from, subject, date, body: body.slice(0, 1200) } });
}
return out;

const cfg = $('Set config: search & categories').first().json;
const emails = $input.all().map((it) => it.json);
const schema = { type: 'object', additionalProperties: false, required: ['receipts'], properties: {
  receipts: { type: 'array', items: { type: 'object', additionalProperties: false,
    required: ['i', 'is_receipt', 'vendor', 'amount', 'currency', 'date', 'category', 'invoice_no'], properties: {
      i: { type: 'integer' }, is_receipt: { type: 'boolean' }, vendor: { type: 'string' },
      amount: { type: 'number' }, currency: { type: 'string' }, date: { type: 'string' },
      category: { type: 'string' }, invoice_no: { type: 'string' } } } } } };
const system = 'You extract structured expense data from receipt and invoice emails. For each email decide is_receipt (true only if it is an actual purchase receipt/invoice, not marketing). Extract vendor, total amount (number only), currency (ISO code, default ' + cfg.defaultCurrency + '), the purchase date as YYYY-MM-DD, an invoice/order number if present (else ""), and category chosen from: ' + cfg.categories + '. If a field is unknown use "" or 0. Do not invent amounts.';
const user = 'EMAILS (reference each by index i):\n' +
  emails.map((e) => '[' + e.i + '] From: ' + e.from + ' | Subject: ' + e.subject + ' | Date: ' + e.date + '\n' + e.body).join('\n\n');
return [{ json: { body: {
  model: cfg.model, max_tokens: 2000, system,
  messages: [{ role: 'user', content: user }],
  output_config: { format: { type: 'json_schema', schema } },
} } }];

const emails = $('Prepare email records').all().map((it) => it.json);
const blocks = ($json.content || []);
const text = (blocks.find((b) => b.type === 'text') || {}).text || '{"receipts":[]}';
let receipts = [];
try { receipts = (JSON.parse(text).receipts) || []; } catch (e) {}
const rows = receipts.filter((r) => r.is_receipt && (r.amount || r.vendor)).map((r) => {
  const src = emails[r.i] || {};
  return { json: {
    date: r.date || '', vendor: r.vendor || '', amount: r.amount ?? '', currency: r.currency || '',
    category: r.category || 'Other', invoice_no: r.invoice_no || '',
    email_subject: src.subject || '', email_from: src.from || '',
  } };
});
return rows.length ? rows : [];
